-- SRV7 W18. Generated rule values from Crystal 201189f871d23597b82caf88fd611454a2ddefb8.
-- data/items/items.xml (wrapableto/rotateto), data-crystal/scripts/actions/other/
-- construction_kits.lua:1-58, data-global/scripts/actions/other/kits.lua:1-14,
-- data/scripts/actions/items/decay_to.lua:6-511. All existing custody/ACL/session
-- and immutable-receipt proofs remain authoritative.
CREATE TABLE game_house_furniture_rules (
 action SMALLINT NOT NULL CHECK(action BETWEEN 1 AND 4),
 first_item INTEGER NOT NULL CHECK(first_item>0),
 last_item INTEGER NOT NULL CHECK(last_item>=first_item),
 result_item INTEGER NOT NULL CHECK(result_item>0),
 PRIMARY KEY(action,first_item,result_item)
);
REVOKE ALL ON game_house_furniture_rules FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_house_furniture_rules TO oteryn_game_runtime,oteryn_game_control;

ALTER FUNCTION game_house_furniture_wrap_pair(UUID,TEXT,TEXT,SMALLINT)
 RENAME TO game_house_furniture_wrap_pair_before_srv7;
CREATE FUNCTION game_house_furniture_wrap_pair(p_item UUID,p_before TEXT,p_after TEXT,p_action SMALLINT)
 RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER STRICT AS $$
 SELECT game_house_furniture_wrap_pair_before_srv7(p_item,p_before,p_after,p_action)
  OR EXISTS(SELECT 1 FROM game_house_furniture_rules c
   WHERE c.action=p_action AND p_after='oteryn:item.tibia.i'||c.result_item::text
    AND p_before ~ '^oteryn:item[.]tibia[.]i[1-9][0-9]{0,8}$'
    AND (CASE WHEN p_before ~ '^oteryn:item[.]tibia[.]i[1-9][0-9]{0,8}$'
      THEN substring(p_before FROM 20)::integer ELSE 0 END) BETWEEN c.first_item AND c.last_item)
  OR (p_action=2 AND EXISTS(SELECT 1 FROM game_house_furniture_wrap_receipts r
   WHERE r.item_instance_id=p_item AND r.action=1 AND r.after_key=p_before
    AND r.before_item->>'definition_production_key'=p_after))
$$;

-- A real carried construction kit is itself its source provenance. A generic
-- decoration kit still requires its original NPC provenance or an exact prior
-- wrap receipt; a client-provided target can never manufacture that metadata.
DO $migration$ DECLARE body TEXT; needle TEXT; replacement TEXT; BEGIN
 SELECT pg_get_functiondef('game_house_furniture_wrap(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)'::regprocedure) INTO STRICT body;
 needle:=$old$AND NOT EXISTS(SELECT 1 FROM game_house_furniture_kit_origins k
      WHERE k.item_instance_id=p_item AND k.target_key=p_after AND k.target_revision=i.definition_revision_ref
       AND i.definition_production_key='oteryn:item.tibia.i23398')) THEN RAISE EXCEPTION 'WRAP_NOT_WRAPABLE'; END IF;$old$;
 replacement:=$new$AND NOT EXISTS(SELECT 1 FROM game_house_furniture_kit_origins k
      WHERE k.item_instance_id=p_item AND k.target_key=p_after AND k.target_revision=i.definition_revision_ref
       AND i.definition_production_key='oteryn:item.tibia.i23398')
    AND NOT EXISTS(SELECT 1 FROM game_house_furniture_rules c WHERE c.action=2
      AND i.definition_production_key='oteryn:item.tibia.i'||c.first_item::text
      AND p_after='oteryn:item.tibia.i'||c.result_item::text)) THEN RAISE EXCEPTION 'WRAP_NOT_WRAPABLE'; END IF;$new$;
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing existing construction-kit origin proof'; END IF;
 EXECUTE replace(body,needle,replacement);
END $migration$;

ALTER FUNCTION game_item_action_house_pair(TEXT,TEXT) RENAME TO game_item_action_house_pair_before_srv7;
CREATE FUNCTION game_item_action_house_pair(p_before TEXT,p_after TEXT) RETURNS BOOLEAN
 LANGUAGE sql STABLE SECURITY DEFINER STRICT AS $$
 SELECT game_item_action_house_pair_before_srv7(p_before,p_after)
  OR EXISTS(SELECT 1 FROM game_house_furniture_rules c WHERE c.action IN(3,4)
   AND p_before='oteryn:item.tibia.i'||c.first_item::text
   AND p_after='oteryn:item.tibia.i'||c.result_item::text)
$$;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY[
  'game_house_furniture_wrap_pair(UUID,TEXT,TEXT,SMALLINT)'::regprocedure,
  'game_item_action_house_pair(TEXT,TEXT)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;

-- Continuous lamps and short decoration animations reuse the existing timed Item rows.
-- This is source lifetime population, not an additional clock or scheduling store.
CREATE TABLE game_house_furniture_lifetimes (
 item_id INTEGER PRIMARY KEY CHECK(item_id>0),
 duration_ms BIGINT CHECK(duration_ms BETWEEN 1 AND 604800000),
 target_id INTEGER CHECK(target_id>0),
 stop_duration BOOLEAN NOT NULL
);
REVOKE ALL ON game_house_furniture_lifetimes FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_house_furniture_lifetimes TO oteryn_game_runtime,oteryn_game_control;

CREATE FUNCTION game_house_furniture_timer_proposal(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE before_timer JSONB; lifetime game_house_furniture_lifetimes%ROWTYPE;
BEGIN
 SELECT to_jsonb(t) INTO before_timer FROM game_item_timed_states t WHERE t.item_instance_id=r.source_item_instance_id;
 IF NOT (r.effects ? 'house_temporal') THEN RETURN before_timer IS NULL; END IF;
 SELECT * INTO lifetime FROM game_house_furniture_lifetimes
  WHERE 'oteryn:item.tibia.i'||item_id::text=r.effects->'house_after'->>'key';
 RETURN before_timer IS NOT DISTINCT FROM nullif(r.effects->'house_temporal'->'before','null'::jsonb)
  AND (before_timer->>'charges') IS NULL
  AND ((before_timer->>'deadline_at')::bigint IS NULL OR (before_timer->>'deadline_at')::bigint>r.occurred_at)
  AND nullif(r.effects->'house_temporal'->'duration','null'::jsonb) IS NOT DISTINCT FROM to_jsonb(lifetime.duration_ms)
  AND nullif(r.effects->'house_temporal'->'target','null'::jsonb)
   IS NOT DISTINCT FROM to_jsonb('oteryn:item.tibia.i'||lifetime.target_id::text);
END $$;

-- A source action may update its existing clock only with that same immutable receipt.
-- Its before row is observed under the existing named-House source locks.
CREATE FUNCTION game_house_furniture_timer_values(r game_item_consume_transform_records)
 RETURNS TABLE(remaining BIGINT,deadline BIGINT) LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE old_row JSONB:=r.effects->'house_temporal'->'before'; life game_house_furniture_lifetimes%ROWTYPE;
 old_remaining BIGINT:=(old_row->>'remaining_ms')::bigint; old_deadline BIGINT:=(old_row->>'deadline_at')::bigint;
 source_stops BOOLEAN;
BEGIN
 SELECT * INTO life FROM game_house_furniture_lifetimes WHERE 'oteryn:item.tibia.i'||item_id::text=r.effects->'house_after'->>'key';
 SELECT stop_duration INTO source_stops FROM game_house_furniture_lifetimes
  WHERE 'oteryn:item.tibia.i'||item_id::text=r.before_item->>'definition_production_key';
 IF r.effects->>'house_wrap_action'='1' THEN
  remaining:=CASE WHEN old_deadline IS NOT NULL THEN greatest(0,least(old_remaining,old_deadline-r.occurred_at)) ELSE old_remaining END;deadline:=NULL;
 ELSIF r.effects->>'house_rotate'='true' AND old_remaining IS NOT NULL AND life.duration_ms IS NOT NULL THEN
  remaining:=least(old_remaining,life.duration_ms);
  IF old_deadline IS NOT NULL THEN remaining:=greatest(0,least(remaining,old_deadline-r.occurred_at)); END IF;
  deadline:=coalesce(old_deadline,r.occurred_at+remaining);
 ELSIF life.duration_ms IS NOT NULL THEN
  remaining:=CASE WHEN (source_stops OR r.effects->>'house_wrap_action'='2') AND old_remaining IS NOT NULL THEN least(old_remaining,life.duration_ms) ELSE life.duration_ms END;
  deadline:=r.occurred_at+remaining;
 ELSIF life.stop_duration THEN
  remaining:=CASE WHEN old_deadline IS NOT NULL THEN greatest(0,least(old_remaining,old_deadline-r.occurred_at)) ELSE old_remaining END;
  deadline:=NULL;
 ELSE remaining:=NULL;deadline:=NULL;
 END IF;
 RETURN NEXT;
END $$;

-- A placement starts a furniture ItemType clock; wrapping pauses its remaining
-- budget and unwrapping resumes it on the same instance. The original wrap
-- receipt supplies the same-XID before timer; no second receipt store is needed.
ALTER TABLE game_house_furniture_wrap_receipts
 ADD COLUMN before_timer JSONB,
 ADD COLUMN acted_at BIGINT NOT NULL DEFAULT floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_house_furniture_wrap(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)'::regprocedure);
 needle:='OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=p_item)';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing wrap timer admission'; END IF;
 body:=replace(body,needle,'OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=p_item AND charges IS NOT NULL)');
 needle:='world_id,house_key,intent,action,before_item,after_key,house_location,inventory_location)';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing wrap timer snapshot columns'; END IF;
 body:=replace(body,needle,'world_id,house_key,intent,action,before_item,after_key,house_location,inventory_location,before_timer)');
 needle:='VALUES(tx,p_session,p_command,p_character,p_item,p_world,p_house,p_intent,p_action,to_jsonb(i),p_after,to_jsonb(h),to_jsonb(e));';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing wrap timer snapshot values'; END IF;
 body:=replace(body,needle,'VALUES(tx,p_session,p_command,p_character,p_item,p_world,p_house,p_intent,p_action,to_jsonb(i),p_after,to_jsonb(h),to_jsonb(e),(SELECT to_jsonb(t) FROM game_item_timed_states t WHERE t.item_instance_id=p_item));');
 EXECUTE body;
END $migration$;

CREATE FUNCTION game_house_furniture_timer_record(p_tx UUID) RETURNS game_item_consume_transform_records
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE; w game_house_furniture_wrap_receipts%ROWTYPE;
 life game_house_furniture_lifetimes%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_tx AND (source_kind=5 OR (source_kind IN(1,4) AND (effects->>'kind'='furniture_rotation' OR effects->>'portable_use'='true')));
 IF FOUND THEN RETURN r; END IF;
 SELECT * INTO w FROM game_house_furniture_wrap_receipts WHERE transaction_id=p_tx;
 IF NOT FOUND THEN RETURN r; END IF;
 r.transaction_id:=w.transaction_id;r.source_kind:=5;r.created_xact_id:=w.created_xact_id;
 r.source_item_instance_id:=w.item_instance_id;r.before_item:=w.before_item;r.occurred_at:=w.acted_at;
 r.effects:=jsonb_build_object('house_after',jsonb_build_object('key',w.after_key,'revision',w.before_item->>'definition_revision_ref'),
  'house_wrap_action',w.action);
 SELECT * INTO life FROM game_house_furniture_lifetimes WHERE 'oteryn:item.tibia.i'||item_id::text=w.after_key;
 IF w.before_timer IS NOT NULL OR life.duration_ms IS NOT NULL THEN
  r.effects:=r.effects||jsonb_build_object('house_temporal',jsonb_build_object('before',w.before_timer,
   'duration',life.duration_ms,'target','oteryn:item.tibia.i'||life.target_id::text));
 END IF;
 RETURN r;
END $$;

ALTER FUNCTION game_house_furniture_wrap(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)
 RENAME TO game_house_furniture_wrap_before_srv7_timers;
CREATE FUNCTION game_house_furniture_wrap(p_session UUID,p_character UUID,p_connection NUMERIC,
 p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT,
 p_command NUMERIC,p_item UUID,p_revision NUMERIC,p_acl NUMERIC,p_action SMALLINT,p_position BYTEA,
 p_intent BYTEA,p_after TEXT,p_capacity INTEGER,p_backpack TEXT) RETURNS NUMERIC LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE result NUMERIC; tx UUID;
BEGIN
 result:=game_house_furniture_wrap_before_srv7_timers(p_session,p_character,p_connection,p_lease,p_scope,p_node,p_node_revision,
  p_world,p_house,p_command,p_item,p_revision,p_acl,p_action,p_position,p_intent,p_after,p_capacity,p_backpack);
 SELECT transaction_id INTO tx FROM game_house_furniture_wrap_receipts WHERE game_session_id=p_session AND command_id=p_command
  AND created_xact_id=pg_current_xact_id();
 IF tx IS NOT NULL THEN PERFORM game_house_furniture_timer_apply(tx); END IF;
 RETURN result;
END $$;

CREATE FUNCTION game_house_furniture_timer_apply(p_tx UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE; t game_item_timed_states%ROWTYPE;
 w game_item_timed_state_writes%ROWTYPE; v RECORD; duration BIGINT;
BEGIN
 r:=game_house_furniture_timer_record(p_tx);
 IF r.transaction_id IS NULL OR NOT(r.effects ? 'house_temporal') THEN RETURN; END IF;
 SELECT * INTO t FROM game_item_timed_states WHERE item_instance_id=r.source_item_instance_id FOR UPDATE;
 IF (CASE WHEN t.item_instance_id IS NULL THEN NULL ELSE to_jsonb(t) END) IS DISTINCT FROM nullif(r.effects->'house_temporal'->'before','null'::jsonb)
  THEN RAISE EXCEPTION 'House decoration timer changed' USING ERRCODE='23514'; END IF;
 SELECT * INTO v FROM game_house_furniture_timer_values(r);
 duration:=(r.effects->'house_temporal'->>'duration')::bigint;
 w.training_created_xact_id:=pg_current_xact_id();
 w.item_instance_id:=r.source_item_instance_id;w.expected_revision:=coalesce(t.state_revision,0);
 w.cause:=CASE WHEN v.deadline IS NOT NULL THEN 5 ELSE 6 END;w.transaction_id:=r.transaction_id;
 w.definition_before_family:='Item';w.definition_before_production_key:=r.before_item->>'definition_production_key';
 w.definition_before_revision_ref:=r.before_item->>'definition_revision_ref';w.definition_after_family:='Item';
 w.definition_after_production_key:=r.effects->'house_after'->>'key';w.definition_after_revision_ref:=r.effects->'house_after'->>'revision';
 w.full_remaining_ms:=duration;w.lit_continuous:=v.deadline IS NOT NULL;
 w.remaining_ms_before:=t.remaining_ms;w.deadline_before:=t.deadline_at;
 w.remaining_ms_after:=v.remaining;w.deadline_after:=v.deadline;
 IF duration IS NOT NULL THEN
   ON CONFLICT DO NOTHING;
 END IF;
 IF t.item_instance_id IS NULL THEN
 ELSE UPDATE game_item_timed_states SET charges=NULL,remaining_ms=v.remaining,deadline_at=v.deadline,state_revision=state_revision+1
  WHERE item_instance_id=w.item_instance_id;
 END IF;
END $$;

CREATE FUNCTION game_house_furniture_timer_action_complete(w game_item_timed_state_writes) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE; v RECORD; before_timer JSONB;
BEGIN
 r:=game_house_furniture_timer_record(w.transaction_id);
 IF r.transaction_id IS NULL OR NOT(r.effects ? 'house_temporal') OR r.created_xact_id<>pg_current_xact_id()
  OR w.created_xact_id<>pg_current_xact_id() OR w.item_instance_id<>r.source_item_instance_id
  OR w.holder_character_id IS NOT NULL OR w.full_charges IS NOT NULL OR w.charges_before IS NOT NULL
  OR w.charges_after IS NOT NULL OR w.committed_at<r.occurred_at THEN RETURN FALSE; END IF;
 before_timer:=r.effects->'house_temporal'->'before';
 SELECT * INTO v FROM game_house_furniture_timer_values(r);
 RETURN w.expected_revision=coalesce((before_timer->>'state_revision')::numeric,0)
  AND w.cause=CASE WHEN v.deadline IS NOT NULL THEN 5 ELSE 6 END
  AND w.definition_before_family='Item' AND w.definition_after_family='Item'
  AND w.definition_before_production_key=r.before_item->>'definition_production_key'
  AND w.definition_before_revision_ref=r.before_item->>'definition_revision_ref'
  AND w.definition_after_production_key=r.effects->'house_after'->>'key'
  AND w.definition_after_revision_ref=r.effects->'house_after'->>'revision'
  AND w.remaining_ms_before IS NOT DISTINCT FROM (before_timer->>'remaining_ms')::bigint
  AND w.deadline_before IS NOT DISTINCT FROM (before_timer->>'deadline_at')::bigint
  AND w.remaining_ms_after IS NOT DISTINCT FROM v.remaining AND w.deadline_after IS NOT DISTINCT FROM v.deadline
  AND w.full_remaining_ms IS NOT DISTINCT FROM (r.effects->'house_temporal'->>'duration')::bigint
  AND w.lit_continuous=(v.deadline IS NOT NULL)
  AND EXISTS(SELECT 1 FROM game_item_timed_states t WHERE t.item_instance_id=w.item_instance_id
   AND t.state_revision=w.expected_revision+1 AND t.charges IS NULL
   AND t.remaining_ms IS NOT DISTINCT FROM w.remaining_ms_after AND t.deadline_at IS NOT DISTINCT FROM w.deadline_after);
END $$;

DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_item_action_house_admit(game_item_consume_transform_records)'::regprocedure);
 needle:='OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id)';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing House timer admission'; END IF;
 EXECUTE replace(body,needle,'OR game_house_furniture_timer_proposal(r) IS DISTINCT FROM TRUE');
 body:=pg_get_functiondef('game_item_timed_state_write_consistency_guard()'::regprocedure);
 EXECUTE overlay(body placing E'BEGIN\n IF game_house_furniture_timer_action_complete(NEW) THEN RETURN NULL; END IF;\n'
  from regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i') for 5);
END $migration$;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY[
  'game_house_furniture_timer_record(UUID)'::regprocedure,
  'game_house_furniture_wrap(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)'::regprocedure,
  'game_house_furniture_timer_proposal(game_item_consume_transform_records)'::regprocedure,
  'game_house_furniture_timer_values(game_item_consume_transform_records)'::regprocedure,
  'game_house_furniture_timer_apply(UUID)'::regprocedure,
  'game_house_furniture_timer_action_complete(game_item_timed_state_writes)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION game_house_furniture_timer_apply(UUID),
 game_house_furniture_wrap(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)
 TO oteryn_game_runtime;

-- The existing timed row has no House/session context. Retain that exact
-- authority and before/after snapshots in one immutable receipt for its expiry.
CREATE TABLE game_house_decoration_decay_receipts (
 transaction_id UUID PRIMARY KEY REFERENCES game_item_timed_state_writes(transaction_id) DEFERRABLE INITIALLY DEFERRED,
 character_id UUID NOT NULL REFERENCES game_character_roots,
 context JSONB NOT NULL,
 before_item JSONB NOT NULL,after_item JSONB NOT NULL,
 before_timer JSONB NOT NULL,after_timer JSONB NOT NULL,
 location JSONB NOT NULL,provenance JSONB NOT NULL,
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id()
);
CREATE INDEX game_house_decoration_decay_character ON game_house_decoration_decay_receipts(character_id);
REVOKE ALL ON game_house_decoration_decay_receipts FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_house_decoration_decay_receipts TO oteryn_game_runtime,oteryn_game_control;
CREATE TRIGGER game_house_decoration_decay_immutable BEFORE UPDATE OR DELETE ON game_house_decoration_decay_receipts
 FOR EACH ROW EXECUTE FUNCTION game_item_immutable();
CREATE TRIGGER game_house_decoration_decay_no_truncate BEFORE TRUNCATE ON game_house_decoration_decay_receipts
 EXECUTE FUNCTION game_item_reject_truncate();

-- Skip complete cosmetic cycles after an unoccupied House was overdue. The
-- next phase remains source-authored, so at most four regular ticks settle a
-- clock/tesseract regardless of how long the House was empty.
CREATE FUNCTION game_house_furniture_cycle_ms(p_item INTEGER) RETURNS BIGINT LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE current_item INTEGER:=p_item; total BIGINT:=0; step INTEGER; life game_house_furniture_lifetimes%ROWTYPE;
BEGIN
 FOR step IN 1..16 LOOP
  SELECT * INTO life FROM game_house_furniture_lifetimes WHERE item_id=current_item;
  IF NOT FOUND OR life.duration_ms IS NULL OR life.target_id IS NULL THEN RETURN NULL; END IF;
  total:=total+life.duration_ms;current_item:=life.target_id;
  IF current_item=p_item THEN RETURN total; END IF;
 END LOOP;
 RETURN NULL;
END $$;

CREATE FUNCTION game_house_decoration_decay_complete(p_tx UUID) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_house_decoration_decay_receipts%ROWTYPE; w game_item_timed_state_writes%ROWTYPE;
 life game_house_furniture_lifetimes%ROWTYPE; next_life game_house_furniture_lifetimes%ROWTYPE;
 expected JSONB; source_id UUID; after_key TEXT; burned BOOLEAN; kind TEXT; cycle_ms BIGINT; skipped BIGINT;
BEGIN
 SELECT * INTO r FROM game_house_decoration_decay_receipts WHERE transaction_id=p_tx;
 SELECT * INTO w FROM game_item_timed_state_writes WHERE transaction_id=p_tx;
 IF r.transaction_id IS NULL OR w.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id()
  OR w.created_xact_id<>pg_current_xact_id() OR w.cause<>4 OR w.holder_character_id IS DISTINCT FROM r.character_id
  OR w.committed_at<(r.before_timer->>'deadline_at')::bigint
  OR (r.before_timer->>'deadline_at') IS NULL OR w.charges_before IS NOT NULL OR w.charges_after IS NOT NULL
  OR w.full_charges IS NOT NULL THEN RETURN FALSE; END IF;
 PERFORM game_house_podium_fence((r.context->>'session')::uuid,r.character_id,
  (r.context->>'connection')::numeric,(r.context->>'lease')::numeric,(r.context->>'scope')::numeric,
  (r.context->>'node')::uuid,(r.context->>'node_revision')::numeric,
  (r.context->>'world')::uuid,r.context->>'house');
 source_id:=(r.before_item->>'item_instance_id')::uuid;
 SELECT * INTO life FROM game_house_furniture_lifetimes
  WHERE 'oteryn:item.tibia.i'||item_id::text=r.before_item->>'definition_production_key';
 IF NOT FOUND OR life.duration_ms IS NULL OR source_id<>w.item_instance_id
  OR r.before_item->>'definition_family'<>'Item' OR r.before_item->>'lifecycle'<>'1'
  OR r.before_item->>'quantity'<>'1' OR r.before_timer->>'item_instance_id'<>source_id::text
  OR w.expected_revision<>(r.before_timer->>'state_revision')::numeric
  OR w.remaining_ms_before IS DISTINCT FROM (r.before_timer->>'remaining_ms')::bigint
  OR w.deadline_before IS DISTINCT FROM (r.before_timer->>'deadline_at')::bigint THEN RETURN FALSE; END IF;
 cycle_ms:=game_house_furniture_cycle_ms(life.item_id);
 skipped:=CASE WHEN cycle_ms IS NULL THEN 0 ELSE
  (((r.context->>'settled_at')::bigint-w.deadline_before)/cycle_ms)*cycle_ms END;
 IF (r.context->>'settled_at')::bigint<w.deadline_before
  OR (r.context->>'settled_at')::bigint>w.committed_at THEN RETURN FALSE; END IF;
 burned:=life.target_id IS NULL;
 after_key:=CASE WHEN burned THEN r.before_item->>'definition_production_key' ELSE 'oteryn:item.tibia.i'||life.target_id::text END;
 SELECT * INTO next_life FROM game_house_furniture_lifetimes WHERE item_id=life.target_id;
 expected:=r.before_item||jsonb_build_object('definition_production_key',after_key,'last_transaction_id',p_tx,
  'state_revision',(r.before_item->>'state_revision')::numeric+1,
  'quantity',CASE WHEN burned THEN 0 ELSE 1 END,'lifecycle',CASE WHEN burned THEN 2 ELSE 1 END);
 IF r.after_item<>expected OR w.definition_before_family<>'Item' OR w.definition_after_family<>'Item'
  OR w.definition_before_production_key<>r.before_item->>'definition_production_key'
  OR w.definition_before_revision_ref<>r.before_item->>'definition_revision_ref'
  OR w.definition_after_production_key<>after_key OR w.definition_after_revision_ref<>r.before_item->>'definition_revision_ref'
  OR w.remaining_ms_after IS DISTINCT FROM next_life.duration_ms
  OR w.deadline_after IS DISTINCT FROM w.deadline_before+next_life.duration_ms+skipped
  OR w.full_remaining_ms IS DISTINCT FROM next_life.duration_ms OR w.lit_continuous<>(next_life.duration_ms IS NOT NULL)
  OR NOT EXISTS(SELECT 1 FROM game_item_instances i WHERE i.item_instance_id=source_id AND to_jsonb(i)=r.after_item)
  THEN RETURN FALSE; END IF;
 expected:=r.before_timer||jsonb_build_object('charges',NULL,'remaining_ms',w.remaining_ms_after,
  'deadline_at',w.deadline_after,'state_revision',w.expected_revision+1);
 IF r.after_timer<>expected OR NOT EXISTS(SELECT 1 FROM game_item_timed_states t
  WHERE t.item_instance_id=source_id AND to_jsonb(t)=r.after_timer) THEN RETURN FALSE; END IF;
 kind:=r.location->>'custody_kind';
 IF burned THEN RETURN
  NOT EXISTS(SELECT 1 FROM game_item_house_interior_locations WHERE item_instance_id=source_id)
  AND NOT EXISTS(SELECT 1 FROM game_item_house_reclaim_provenance WHERE item_instance_id=source_id)
  AND NOT EXISTS(SELECT 1 FROM game_item_container_entries WHERE item_instance_id=source_id)
  AND NOT EXISTS(SELECT 1 FROM game_item_nested_entries WHERE item_instance_id=source_id)
  AND NOT EXISTS(SELECT 1 FROM game_character_equipment_slots WHERE item_instance_id=source_id);
 END IF;
 RETURN CASE kind
  WHEN 'house' THEN EXISTS(SELECT 1 FROM game_item_house_interior_locations h JOIN game_item_house_reclaim_provenance p USING(item_instance_id)
   WHERE h.item_instance_id=source_id AND to_jsonb(h)=r.location->'custody' AND to_jsonb(p)=r.provenance)
  WHEN 'container' THEN EXISTS(SELECT 1 FROM game_item_container_entries c WHERE c.item_instance_id=source_id AND to_jsonb(c)=r.location->'custody' AND c.character_id=r.character_id)
  WHEN 'nested' THEN EXISTS(SELECT 1 FROM game_item_nested_entries c,LATERAL game_item_loop_owner(c.parent_item_instance_id) owner
   WHERE c.item_instance_id=source_id AND to_jsonb(c)=r.location->'custody' AND owner.owner_character=r.character_id AND owner.depth BETWEEN 0 AND 7)
  WHEN 'equipment' THEN EXISTS(SELECT 1 FROM game_character_equipment_slots c WHERE c.item_instance_id=source_id AND to_jsonb(c)=r.location->'custody' AND c.character_id=r.character_id)
  ELSE FALSE END;
END $$;
CREATE FUNCTION game_house_decoration_decay_proven() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF game_house_decoration_decay_complete(NEW.transaction_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'incomplete fenced House decoration expiry' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_house_decoration_decay_proven AFTER INSERT ON game_house_decoration_decay_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_house_decoration_decay_proven();

CREATE FUNCTION game_house_decoration_decay_expire(p_session UUID,p_character UUID,p_connection NUMERIC,
 p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT)
 RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c RECORD; src RECORD; t game_item_timed_states%ROWTYPE; w game_item_timed_state_writes%ROWTYPE;
 life game_house_furniture_lifetimes%ROWTYPE; next_life game_house_furniture_lifetimes%ROWTYPE;
 before_item JSONB;after_item JSONB;after_timer JSONB;tx UUID; total INTEGER:=0;burned BOOLEAN; settled BIGINT;cycle_ms BIGINT;skipped BIGINT;
BEGIN
 PERFORM game_house_podium_fence(p_session,p_character,p_connection,p_lease,p_scope,p_node,p_node_revision,p_world,p_house);
 PERFORM 1 FROM game_character_roots WHERE character_id=p_character FOR UPDATE;
 PERFORM 1 FROM game_house_properties WHERE world_id=p_world AND house_key=p_house FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended('oteryn:house-items:'||p_world::text||':'||p_house,0));
 FOR c IN SELECT i.item_instance_id FROM game_item_instances i JOIN game_item_timed_states timer USING(item_instance_id)
  JOIN game_house_furniture_lifetimes lifetime ON 'oteryn:item.tibia.i'||lifetime.item_id::text=i.definition_production_key
  LEFT JOIN game_item_house_interior_locations h USING(item_instance_id)
  LEFT JOIN LATERAL game_item_loop_owner(i.item_instance_id) owner ON TRUE
  WHERE i.world_id=p_world AND i.lifecycle=1 AND i.quantity=1 AND lifetime.duration_ms IS NOT NULL
   AND timer.deadline_at<=floor(extract(epoch FROM clock_timestamp())*1000)::bigint
   AND ((h.world_id=p_world AND h.house_key=p_house) OR owner.owner_character=p_character)
  ORDER BY i.item_instance_id LIMIT 16 FOR UPDATE OF i,timer LOOP
  SELECT * INTO src FROM game_item_action_house_source(p_session,p_character,p_connection,p_lease,p_scope,
   p_node,p_node_revision,p_world,p_house,c.item_instance_id);
  IF NOT FOUND THEN CONTINUE; END IF;
  before_item:=src.before_item;
  SELECT * INTO t FROM game_item_timed_states WHERE item_instance_id=c.item_instance_id FOR UPDATE;
  SELECT * INTO life FROM game_house_furniture_lifetimes WHERE 'oteryn:item.tibia.i'||item_id::text=before_item->>'definition_production_key';
  SELECT * INTO next_life FROM game_house_furniture_lifetimes WHERE item_id=life.target_id;
  IF t.deadline_at IS NULL OR t.deadline_at>floor(extract(epoch FROM clock_timestamp())*1000)::bigint
   OR t.charges IS NOT NULL OR life.duration_ms IS NULL THEN CONTINUE; END IF;
  tx:=game_character_uuid_v7();burned:=life.target_id IS NULL;
  settled:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
  cycle_ms:=game_house_furniture_cycle_ms(life.item_id);
  skipped:=CASE WHEN cycle_ms IS NULL THEN 0 ELSE ((settled-t.deadline_at)/cycle_ms)*cycle_ms END;
  w:=NULL;w.item_instance_id:=c.item_instance_id;w.expected_revision:=t.state_revision;w.cause:=4;
  w.transaction_id:=tx;w.holder_character_id:=p_character;w.definition_before_family:='Item';w.definition_after_family:='Item';
  w.definition_before_production_key:=before_item->>'definition_production_key';w.definition_before_revision_ref:=before_item->>'definition_revision_ref';
  w.definition_after_production_key:=CASE WHEN burned THEN w.definition_before_production_key ELSE 'oteryn:item.tibia.i'||life.target_id::text END;
  w.definition_after_revision_ref:=w.definition_before_revision_ref;w.lit_continuous:=next_life.duration_ms IS NOT NULL;
  w.full_remaining_ms:=next_life.duration_ms;w.remaining_ms_before:=t.remaining_ms;w.deadline_before:=t.deadline_at;
  w.remaining_ms_after:=next_life.duration_ms;w.deadline_after:=t.deadline_at+next_life.duration_ms+skipped;
  after_item:=before_item||jsonb_build_object('definition_production_key',w.definition_after_production_key,
   'last_transaction_id',tx,'state_revision',(before_item->>'state_revision')::numeric+1,
   'quantity',CASE WHEN burned THEN 0 ELSE 1 END,'lifecycle',CASE WHEN burned THEN 2 ELSE 1 END);
  after_timer:=to_jsonb(t)||jsonb_build_object('charges',NULL,'remaining_ms',w.remaining_ms_after,
   'deadline_at',w.deadline_after,'state_revision',t.state_revision+1);
   VALUES(tx,p_character,jsonb_build_object('session',p_session,'connection',p_connection,'lease',p_lease,'scope',p_scope,
    'node',p_node,'node_revision',p_node_revision,'world',p_world,'house',p_house,'settled_at',settled),before_item,after_item,to_jsonb(t),after_timer,src.location,src.provenance);
  UPDATE game_item_instances SET definition_production_key=w.definition_after_production_key,last_transaction_id=tx,
   state_revision=state_revision+1,quantity=CASE WHEN burned THEN 0 ELSE 1 END,lifecycle=CASE WHEN burned THEN 2 ELSE 1 END
   WHERE item_instance_id=c.item_instance_id;
  UPDATE game_item_timed_states SET charges=NULL,remaining_ms=w.remaining_ms_after,deadline_at=w.deadline_after,state_revision=state_revision+1
   WHERE item_instance_id=c.item_instance_id;
  IF burned THEN
   DELETE FROM game_item_house_reclaim_provenance WHERE item_instance_id=c.item_instance_id;
   DELETE FROM game_item_house_interior_locations WHERE item_instance_id=c.item_instance_id;
   DELETE FROM game_item_container_entries WHERE item_instance_id=c.item_instance_id;
   DELETE FROM game_item_nested_entries WHERE item_instance_id=c.item_instance_id;
   DELETE FROM game_character_equipment_slots WHERE item_instance_id=c.item_instance_id;
  END IF;
  total:=total+1;
 END LOOP;
 RETURN total;
END $$;

-- Existing guards accept only this exact current-XID receipt; every previous
-- guard body remains present and runs for every other mutation.
DO $migration$ DECLARE name TEXT; body TEXT; arm TEXT; begin_at INTEGER; BEGIN
 FOREACH name IN ARRAY ARRAY['game_item_instance_guard','game_item_instance_change_proven',
  'game_item_timed_state_write_consistency_guard','game_house_location_proven',
  'game_item_container_entry_removal_proven','game_item_nested_entry_proven'] LOOP
  body:=pg_get_functiondef((name||'()')::regprocedure);
  begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
  IF begin_at=0 THEN RAISE EXCEPTION 'SRV7 missing decoration timer guard: %',name; END IF;
  IF name='game_item_instance_guard' THEN arm:=$arm$
   IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM game_house_decoration_decay_receipts srv7_furniture_receipt WHERE
    srv7_furniture_receipt.transaction_id=NEW.last_transaction_id AND srv7_furniture_receipt.before_item=to_jsonb(OLD) AND srv7_furniture_receipt.after_item=to_jsonb(NEW)
    AND srv7_furniture_receipt.created_xact_id=pg_current_xact_id()) THEN RETURN NEW; END IF;
$arm$;
  ELSIF name='game_item_instance_change_proven' THEN arm:=$arm$
   IF game_house_decoration_decay_complete(NEW.last_transaction_id) THEN RETURN NULL; END IF;
$arm$;
  ELSIF name='game_item_timed_state_write_consistency_guard' THEN arm:=$arm$
   IF game_house_decoration_decay_complete(NEW.transaction_id) THEN RETURN NULL; END IF;
$arm$;
  ELSE arm:=$arm$
   IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM game_house_decoration_decay_receipts srv7_furniture_receipt
    WHERE srv7_furniture_receipt.location->'custody'=to_jsonb(OLD) AND srv7_furniture_receipt.after_item->>'lifecycle'='2'
     AND game_house_decoration_decay_complete(srv7_furniture_receipt.transaction_id)) THEN RETURN NULL; END IF;
$arm$;
  END IF;
  EXECUTE overlay(body placing E'BEGIN\n'||arm from begin_at for 5);
 END LOOP;
END $migration$;

-- Reuse the existing named-House tick, already generation/session fenced by its caller.
ALTER FUNCTION game_house_furniture_destroy_expire(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT)
 RENAME TO game_house_furniture_destroy_expire_before_srv7;
CREATE FUNCTION game_house_furniture_destroy_expire(p_session UUID,p_character UUID,p_connection NUMERIC,
 p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT)
 RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 RETURN game_house_furniture_destroy_expire_before_srv7(p_session,p_character,p_connection,p_lease,p_scope,
  p_node,p_node_revision,p_world,p_house)+game_house_decoration_decay_expire(p_session,p_character,p_connection,p_lease,p_scope,
  p_node,p_node_revision,p_world,p_house);
END $$;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY[
  'game_house_furniture_cycle_ms(INTEGER)'::regprocedure,
  'game_house_decoration_decay_complete(UUID)'::regprocedure,
  'game_house_decoration_decay_proven()'::regprocedure,
  'game_house_decoration_decay_expire(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT)'::regprocedure,
  'game_house_furniture_destroy_expire(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION game_house_furniture_destroy_expire(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT)
 TO oteryn_game_runtime;

-- A rotation keeps a container and every child instance in place. Admit it
-- only when the source-authored target capacity contains all current children.
CREATE TABLE game_house_furniture_capacities (
 item_id INTEGER PRIMARY KEY CHECK(item_id>0),capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 65535)
);
REVOKE ALL ON game_house_furniture_capacities FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_house_furniture_capacities TO oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_house_furniture_container_fits(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT (SELECT count(*) FROM (
  SELECT item_instance_id FROM game_item_container_entries WHERE parent_item_instance_id=r.source_item_instance_id
  UNION ALL SELECT item_instance_id FROM game_item_nested_entries WHERE parent_item_instance_id=r.source_item_instance_id
  UNION ALL SELECT item_instance_id FROM game_item_corpse_container_entries WHERE parent_item_instance_id=r.source_item_instance_id
 ) children)<=coalesce((SELECT capacity FROM game_house_furniture_capacities
  WHERE 'oteryn:item.tibia.i'||item_id::text=r.effects->'house_after'->>'key'),0)
$$;
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_item_action_house_admit(game_item_consume_transform_records)'::regprocedure);
 needle:=$old$OR EXISTS(SELECT 1 FROM game_item_container_entries WHERE parent_item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_nested_entries WHERE parent_item_instance_id=i.item_instance_id)$old$;
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing House container admission'; END IF;
 EXECUTE replace(body,needle,'OR game_house_furniture_container_fits(r) IS DISTINCT FROM TRUE');
 body:=pg_get_functiondef('game_item_action_house_complete(UUID)'::regprocedure);
 needle:='OR game_item_action_house_custody(r) IS DISTINCT FROM TRUE';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing House container completion'; END IF;
 EXECUTE replace(body,needle,needle||' OR game_house_furniture_container_fits(r) IS DISTINCT FROM TRUE');
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_house_furniture_container_fits(game_item_consume_transform_records) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_house_furniture_container_fits(game_item_consume_transform_records)
 FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- Rotate retargets the original absolute Item schedule; its source and deadline
-- remain unchanged. The complete old row is retained in the immutable action.
CREATE FUNCTION game_house_furniture_absolute_proposal(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE p game_spell_item_temporal_schedules%ROWTYPE; life game_house_furniture_lifetimes%ROWTYPE;
BEGIN
 SELECT * INTO p FROM game_spell_item_temporal_schedules WHERE item_instance_id=r.source_item_instance_id;
 IF NOT (r.effects ? 'house_absolute') THEN RETURN p.item_instance_id IS NULL
  OR EXISTS(SELECT 1 FROM game_spell_item_temporal_receipts done WHERE done.item_instance_id=p.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_house_furniture_absolute_expiries done WHERE done.item_instance_id=p.item_instance_id); END IF;
 SELECT * INTO life FROM game_house_furniture_lifetimes
  WHERE 'oteryn:item.tibia.i'||item_id::text=coalesce(r.effects->'rotate_after',r.effects->'house_after')->>'key';
 RETURN r.effects->>'house_rotate'='true' AND p.item_instance_id IS NOT NULL AND to_jsonb(p)=r.effects->'house_absolute'->'before'
  AND NOT (r.effects ? 'house_temporal')
  AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=p.item_instance_id)
  AND NOT EXISTS(SELECT 1 FROM game_spell_item_temporal_receipts WHERE item_instance_id=p.item_instance_id)
  AND p.expires_at_unix_ms>r.occurred_at AND p.duration_millis=life.duration_ms
  AND (p.definition_family,p.definition_production_key,p.definition_revision)=
   ('Item',r.before_item->>'definition_production_key',r.before_item->>'definition_revision_ref')
  AND life.target_id IS NOT NULL AND p.target_family='Item'
  AND p.target_revision=p.definition_revision
  AND r.effects->'house_absolute'->>'target'='oteryn:item.tibia.i'||life.target_id::text;
END $$;
CREATE FUNCTION game_house_furniture_absolute_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'absolute Item source history is immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM game_item_consume_transform_records
  WHERE source_item_instance_id=OLD.item_instance_id AND created_xact_id=pg_current_xact_id()
   AND ((source_kind IN(1,4) AND effects->>'kind'='furniture_rotation')
    OR (source_kind=5 AND effects->>'kind'='house_transform' AND effects->>'house_rotate'='true'))
   AND effects->'house_absolute'->'before'=to_jsonb(OLD);
 IF r.transaction_id IS NULL OR r.effects ? 'house_temporal'
  OR to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)||jsonb_build_object(
   'definition_production_key',coalesce(r.effects->'rotate_after',r.effects->'house_after')->>'key',
   'target_production_key',r.effects->'house_absolute'->>'target')
  OR NOT EXISTS(SELECT 1 FROM game_item_instances i WHERE i.item_instance_id=OLD.item_instance_id
    AND i.last_transaction_id=r.transaction_id AND i.definition_production_key=NEW.definition_production_key
    AND i.state_revision=(r.before_item->>'state_revision')::numeric+1)
 THEN RAISE EXCEPTION 'absolute Rotate must preserve original source, deadline and exact receipt' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER game_spell_item_temporal_schedules_immutable ON game_spell_item_temporal_schedules;
CREATE TRIGGER game_spell_item_temporal_schedules_immutable BEFORE UPDATE OR DELETE ON game_spell_item_temporal_schedules
 FOR EACH ROW EXECUTE FUNCTION game_house_furniture_absolute_guard();
CREATE FUNCTION game_house_furniture_absolute_apply(p_tx UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_tx;
 IF NOT (r.effects ? 'house_absolute') THEN RETURN; END IF;
 IF r.created_xact_id<>pg_current_xact_id() THEN RAISE EXCEPTION 'absolute Rotate requires original action transaction' USING ERRCODE='23514'; END IF;
 UPDATE game_spell_item_temporal_schedules SET definition_production_key=coalesce(r.effects->'rotate_after',r.effects->'house_after')->>'key',
  target_production_key=r.effects->'house_absolute'->>'target'
  WHERE item_instance_id=r.source_item_instance_id AND to_jsonb(game_spell_item_temporal_schedules)=r.effects->'house_absolute'->'before';
 IF NOT FOUND THEN RAISE EXCEPTION 'absolute Rotate source schedule changed' USING ERRCODE='23514'; END IF;
END $$;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY['game_house_furniture_absolute_proposal(game_item_consume_transform_records)'::regprocedure,
  'game_house_furniture_absolute_guard()'::regprocedure,'game_house_furniture_absolute_apply(uuid)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_control',f);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',f);
 END LOOP;
END $$;

CREATE FUNCTION game_house_furniture_absolute_complete(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT NOT(r.effects ? 'house_absolute') OR EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules p
  WHERE p.item_instance_id=r.source_item_instance_id AND to_jsonb(p)=
   (r.effects->'house_absolute'->'before')||jsonb_build_object(
    'definition_production_key',coalesce(r.effects->'rotate_after',r.effects->'house_after')->>'key',
    'target_production_key',r.effects->'house_absolute'->>'target'))
$$;
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_item_action_house_admit(game_item_consume_transform_records)'::regprocedure);
 needle:='OR game_house_furniture_timer_proposal(r) IS DISTINCT FROM TRUE';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'missing House timer proposal'; END IF;
 EXECUTE replace(body,needle,needle||' OR game_house_furniture_absolute_proposal(r) IS DISTINCT FROM TRUE');
 body:=pg_get_functiondef('game_item_action_house_complete(UUID)'::regprocedure);
 needle:='OR game_item_action_house_custody(r) IS DISTINCT FROM TRUE';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'missing House custody completion'; END IF;
 EXECUTE replace(body,needle,needle||' OR game_house_furniture_absolute_complete(r) IS DISTINCT FROM TRUE');
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_house_furniture_absolute_complete(game_item_consume_transform_records) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_house_furniture_absolute_complete(game_item_consume_transform_records) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_house_furniture_absolute_complete(game_item_consume_transform_records) TO oteryn_game_runtime;

-- Source-captured portable USE subset; carpets and construction kits are excluded.
CREATE TABLE game_house_furniture_portable_use(first_item INTEGER PRIMARY KEY,result_item INTEGER NOT NULL);
REVOKE ALL ON game_house_furniture_portable_use FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_house_furniture_portable_use TO oteryn_game_runtime,oteryn_game_control;
-- Portable native Rotate shares the existing economic Type-2 action receipt.
-- A source pair grants no House authority and never creates House metadata.
CREATE FUNCTION game_item_action_furniture_custody(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT CASE r.source_kind
 WHEN 1 THEN EXISTS(SELECT 1 FROM game_item_container_entries e JOIN game_item_container_slots b
  ON b.character_id=e.character_id AND b.item_instance_id=e.parent_item_instance_id AND b.world_id=e.world_id
  WHERE e.item_instance_id=r.source_item_instance_id AND e.world_id=r.world_id AND e.character_id=r.character_id
   AND e.parent_item_instance_id=r.parent_item_instance_id AND e.placement_ordinal=r.source_ordinal AND to_jsonb(e)=r.source_location)
 WHEN 4 THEN game_item_action_custody_current(r)
 ELSE FALSE END
$$;
CREATE FUNCTION game_item_action_furniture_admit(r game_item_consume_transform_records) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE i game_item_instances%ROWTYPE;
BEGIN
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id FOR UPDATE;
 IF (r.effects->>'kind' IS DISTINCT FROM 'furniture_rotation' AND r.effects->>'portable_use' IS DISTINCT FROM 'true') OR r.source_kind NOT IN(1,4)
  OR r.consume_source OR r.source_count<>0 OR r.outputs<>'[]'::jsonb OR r.extra_inputs<>'[]'::jsonb
  OR r.secondary_item_instance_id<>r.source_item_instance_id OR r.before_secondary IS DISTINCT FROM r.before_item
  OR i.item_instance_id IS NULL OR to_jsonb(i) IS DISTINCT FROM r.before_item OR i.lifecycle<>1 OR i.quantity<>1
  OR i.definition_family<>'Item' OR i.world_id<>r.world_id OR i.state_revision>=18446744073709551615
  OR r.content_digest IS NULL
  OR (r.effects->>'kind'='furniture_rotation' AND (octet_length(r.intent)<6 OR get_byte(r.intent,0)<>255))
  OR (r.effects->>'portable_use'='true' AND (r.effects->>'kind' IS DISTINCT FROM 'transform'
   OR r.recipe IS DISTINCT FROM 'oteryn:novelty-item.furniture-use.'||i.definition_production_key||'.v1'
   OR r.effects ? 'house_absolute' OR r.effects->>'house_rotate'='true'
   OR NOT EXISTS(SELECT 1 FROM game_house_furniture_portable_use c
    WHERE i.definition_production_key='oteryn:item.tibia.i'||c.first_item::text
     AND r.effects->'rotate_after'->>'key'='oteryn:item.tibia.i'||c.result_item::text)))
  OR r.effects->'rotate_after'->>'revision' IS DISTINCT FROM i.definition_revision_ref
  OR NOT EXISTS(SELECT 1 FROM game_house_furniture_rules c WHERE c.action=CASE WHEN r.effects->>'portable_use'='true' THEN 3 ELSE 4 END
   AND i.definition_production_key='oteryn:item.tibia.i'||c.first_item::text
   AND r.effects->'rotate_after'->>'key'='oteryn:item.tibia.i'||c.result_item::text)
  OR game_item_action_furniture_custody(r) IS DISTINCT FROM TRUE
  OR (r.effects ? 'house_temporal' AND (r.effects->'house_after' IS DISTINCT FROM r.effects->'rotate_after' OR (r.effects->>'kind'='furniture_rotation' AND r.effects->>'house_rotate' IS DISTINCT FROM 'true')))
  OR game_house_furniture_timer_proposal(r) IS DISTINCT FROM TRUE
  OR game_house_furniture_absolute_proposal(r) IS DISTINCT FROM TRUE
  OR EXISTS(SELECT 1 FROM game_item_house_interior_locations WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_house_reclaim_provenance WHERE item_instance_id=i.item_instance_id)
  OR (SELECT count(*) FROM (SELECT item_instance_id FROM game_item_container_entries WHERE parent_item_instance_id=i.item_instance_id
    UNION ALL SELECT item_instance_id FROM game_item_nested_entries WHERE parent_item_instance_id=i.item_instance_id
    UNION ALL SELECT item_instance_id FROM game_item_corpse_container_entries WHERE parent_item_instance_id=i.item_instance_id) child)
   >coalesce((SELECT capacity FROM game_house_furniture_capacities
    WHERE 'oteryn:item.tibia.i'||item_id::text=r.effects->'rotate_after'->>'key'),0)
  OR game_runtime_scope_assignment_history_valid() IS DISTINCT FROM TRUE
  OR game_node_lock_current_registration((r.effects->>'node_id')::uuid,(r.effects->>'node_revision')::numeric) IS DISTINCT FROM TRUE
  OR NOT EXISTS(SELECT 1 FROM game_durability_reconnect_sessions s
   JOIN game_durability_admission_character_guards c ON c.character_id=s.character_id AND c.account_id=s.account_id
   JOIN game_durability_admission_account_guards a ON a.account_id=c.account_id
   WHERE s.game_session_id=r.game_session_id AND s.character_id=r.character_id AND s.world_id=r.world_id
    AND s.session_state IN(1,2) AND s.runtime_scope_kind=1 AND s.runtime_scope_world_id=r.world_id
    AND s.current_generation=(r.audit_context->>'connection_generation')::numeric
    AND s.character_lease_generation=(r.audit_context->>'lease_generation')::numeric
    AND s.scope_ownership_generation=(r.audit_context->>'scope_generation')::numeric
    AND c.eligible AND c.lease_generation=s.character_lease_generation AND c.holder_game_session_id=s.game_session_id
    AND a.presence_character_id=c.character_id AND a.holder_game_session_id=s.game_session_id
    AND EXISTS(SELECT 1 FROM game_runtime_scope_assignments runtime
     JOIN game_durability_admission_runtime_guards g ON g.scope_key=runtime.scope_key
     WHERE runtime.scope_kind=1 AND runtime.world_id=r.world_id AND runtime.channel_id=s.runtime_scope_channel_id
      AND runtime.state=1 AND runtime.ownership_generation=s.scope_ownership_generation
      AND runtime.holder_node_id=(r.effects->>'node_id')::uuid
      AND runtime.holder_registration_revision=(r.effects->>'node_revision')::numeric
      AND g.ready AND g.ownership_generation=runtime.ownership_generation))
 THEN RAISE EXCEPTION 'portable Rotate requires exact native pair, live Character and unchanged carried custody' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION game_item_action_furniture_complete(p_transaction UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE; i game_item_instances%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction;
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id;
 IF r.transaction_id IS NULL OR (r.effects->>'kind' IS DISTINCT FROM 'furniture_rotation' AND r.effects->>'portable_use' IS DISTINCT FROM 'true')
  OR r.created_xact_id<>pg_current_xact_id() OR r.source_kind NOT IN(1,4)
  OR i.last_transaction_id IS DISTINCT FROM r.transaction_id
  OR i.state_revision IS DISTINCT FROM (r.before_item->>'state_revision')::numeric+1
  OR i.definition_production_key IS DISTINCT FROM r.effects->'rotate_after'->>'key'
  OR i.definition_revision_ref IS DISTINCT FROM r.effects->'rotate_after'->>'revision'
  OR (to_jsonb(i)-ARRAY['definition_production_key','last_transaction_id','state_revision'])
   IS DISTINCT FROM (r.before_item-ARRAY['definition_production_key','last_transaction_id','state_revision'])
  OR game_item_action_furniture_custody(r) IS DISTINCT FROM TRUE
  OR ((r.effects ? 'house_absolute') AND NOT EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules p
    WHERE p.item_instance_id=r.source_item_instance_id AND to_jsonb(p)=
     (r.effects->'house_absolute'->'before')||jsonb_build_object(
      'definition_production_key',r.effects->'rotate_after'->>'key',
      'target_production_key',r.effects->'house_absolute'->>'target')))
  OR EXISTS(SELECT 1 FROM game_item_instances WHERE minted_transaction_id=r.transaction_id)
  OR (SELECT count(*) FROM game_item_instances WHERE last_transaction_id=r.transaction_id)<>1
  OR (SELECT count(*) FROM game_item_audit_outbox WHERE transaction_id=r.transaction_id)<>1
  OR NOT EXISTS(SELECT 1 FROM game_item_audit_outbox WHERE event_id=r.event_id AND transaction_id=r.transaction_id
    AND item_instance_id=r.source_item_instance_id AND occurred_at=r.occurred_at AND envelope_sha256=r.envelope_sha256
    AND created_xact_id=pg_current_xact_id() AND transaction_ordinal=1 AND transaction_count=1
    AND publication_state=1 AND published_at IS NULL)
 THEN RAISE EXCEPTION 'portable Rotate changed instance, custody, lineage or exact audit' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION game_item_action_furniture_apply(p_transaction UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction;
 IF r.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() THEN
  RAISE EXCEPTION 'portable Rotate requires original receipt transaction' USING ERRCODE='23514'; END IF;
 PERFORM game_item_action_furniture_admit(r);
 UPDATE game_item_instances SET definition_production_key=r.effects->'rotate_after'->>'key',
  state_revision=state_revision+1,last_transaction_id=r.transaction_id WHERE item_instance_id=r.source_item_instance_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'portable Rotate source disappeared' USING ERRCODE='23514'; END IF;
END $$;
DO $migration$
DECLARE n TEXT; body TEXT; arm TEXT; begin_at INTEGER;
BEGIN
 FOREACH n IN ARRAY ARRAY['game_item_consume_transform_admit','game_item_consume_transform_complete',
  'game_item_instance_guard','game_item_instance_change_proven'] LOOP
  body:=pg_get_functiondef((n||CASE WHEN n='game_item_consume_transform_complete' THEN '(uuid)' ELSE '()' END)::regprocedure);
  begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
  IF begin_at=0 THEN RAISE EXCEPTION 'missing portable Rotate proof chain: %',n; END IF;
  IF n='game_item_consume_transform_admit' THEN arm:=$arm$
   IF (NEW.effects->>'kind'='furniture_rotation' OR NEW.effects->>'portable_use'='true') THEN
    PERFORM game_item_action_furniture_admit(NEW); NEW.created_xact_id:=pg_current_xact_id(); RETURN NEW;
   END IF;
  $arm$;
  ELSIF n='game_item_consume_transform_complete' THEN arm:=$arm$
   IF EXISTS(SELECT 1 FROM game_item_consume_transform_records WHERE transaction_id=p_transaction AND (effects->>'kind'='furniture_rotation' OR effects->>'portable_use'='true')) THEN
    PERFORM game_item_action_furniture_complete(p_transaction); RETURN;
   END IF;
  $arm$;
  ELSIF n='game_item_instance_guard' THEN arm:=$arm$
   IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM game_item_consume_transform_records srv7_furniture_receipt
    WHERE (srv7_furniture_receipt.effects->>'kind'='furniture_rotation' OR srv7_furniture_receipt.effects->>'portable_use'='true') AND srv7_furniture_receipt.source_kind IN(1,4)
     AND srv7_furniture_receipt.source_item_instance_id=OLD.item_instance_id AND srv7_furniture_receipt.before_item=to_jsonb(OLD)
     AND srv7_furniture_receipt.transaction_id=NEW.last_transaction_id AND srv7_furniture_receipt.created_xact_id=pg_current_xact_id()
     AND NEW.definition_production_key=srv7_furniture_receipt.effects->'rotate_after'->>'key') THEN
    IF NEW.state_revision<>OLD.state_revision+1 OR NEW.lifecycle<>1 OR NEW.quantity<>1
     OR (to_jsonb(NEW)-ARRAY['definition_production_key','last_transaction_id','state_revision']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['definition_production_key','last_transaction_id','state_revision']) THEN
     RAISE EXCEPTION 'portable Rotate transforms one instance in place' USING ERRCODE='23514'; END IF;
    RETURN NEW;
   END IF;
  $arm$;
  ELSE arm:=$arm$
   IF EXISTS(SELECT 1 FROM game_item_consume_transform_records srv7_furniture_receipt WHERE (srv7_furniture_receipt.effects->>'kind'='furniture_rotation' OR srv7_furniture_receipt.effects->>'portable_use'='true')
    AND srv7_furniture_receipt.source_item_instance_id=NEW.item_instance_id AND srv7_furniture_receipt.transaction_id=NEW.last_transaction_id
    AND srv7_furniture_receipt.created_xact_id=pg_current_xact_id()) THEN
    PERFORM game_item_action_furniture_complete(NEW.last_transaction_id); RETURN NULL;
   END IF;
  $arm$;
  END IF;
  EXECUTE substring(body FROM 1 FOR begin_at+4)||E'\n'||arm||substring(body FROM begin_at+5);
 END LOOP;
END $migration$;
DO $access$
DECLARE f regprocedure;
BEGIN
 FOREACH f IN ARRAY ARRAY[
  'game_item_action_furniture_custody(game_item_consume_transform_records)'::regprocedure,
  'game_item_action_furniture_admit(game_item_consume_transform_records)'::regprocedure,
  'game_item_action_furniture_complete(uuid)'::regprocedure,
  'game_item_action_furniture_apply(uuid)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
 -- The merged0589 admission/deferred completion chain runs as invoker.
 -- These validated entry points therefore need EXECUTE; custody stays private.
 GRANT EXECUTE ON FUNCTION game_item_action_furniture_admit(game_item_consume_transform_records),
  game_item_action_furniture_complete(UUID),game_item_action_furniture_apply(UUID) TO oteryn_game_runtime;
END $access$;

-- Ordinary native USE already carries an opaque inventory handle. Retain that
-- original wire intent on the same immutable wrap receipt, without exposing UUIDs.
ALTER TABLE game_house_furniture_wrap_receipts ADD COLUMN use_intent BYTEA
 CHECK(use_intent IS NULL OR octet_length(use_intent) BETWEEN 1 AND 529);

-- Qualify the constructor's source with the same Character->House->Item lock
-- order as the wrap writer, avoiding a shared-to-exclusive House lock upgrade.
CREATE FUNCTION game_house_construction_source(p_session UUID,p_character UUID,p_connection NUMERIC,
 p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT,p_item UUID)
RETURNS TABLE(before_item JSONB,location JSONB,provenance JSONB,spatial_position BYTEA,stack_ordinal TEXT)
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE guild UUID;
BEGIN
 PERFORM game_house_podium_fence(p_session,p_character,p_connection,p_lease,p_scope,p_node,p_node_revision,p_world,p_house);
 PERFORM 1 FROM game_character_roots WHERE character_id=p_character FOR UPDATE;
 SELECT owner_guild_id INTO guild FROM game_house_properties WHERE world_id=p_world AND house_key=p_house;
 IF guild IS NOT NULL THEN PERFORM 1 FROM game_guilds WHERE guild_id=guild AND world_id=p_world FOR SHARE; END IF;
 PERFORM 1 FROM game_house_properties WHERE world_id=p_world AND house_key=p_house FOR UPDATE;
 IF (SELECT owner_guild_id FROM game_house_properties WHERE world_id=p_world AND house_key=p_house) IS DISTINCT FROM guild
  THEN RAISE EXCEPTION 'WRAP_STALE'; END IF;
 RETURN QUERY SELECT * FROM game_item_action_house_source(p_session,p_character,p_connection,p_lease,p_scope,
  p_node,p_node_revision,p_world,p_house,p_item);
END $$;

-- Reuse the existing complete writer body and its authority/lineage checks. The
-- only additional input is the bounded original native USE binding. Existing
-- command402 retains its exact45-byte contract and NULL use_intent.
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_house_furniture_wrap_before_srv7_timers(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)'::regprocedure);
 needle:='game_house_furniture_wrap_before_srv7_timers(';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing constructor writer name'; END IF;
 body:=replace(body,needle,'game_house_furniture_construct(');
 needle:='p_backpack text)';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing constructor parameter signature'; END IF;
 body:=replace(body,needle,'p_backpack text, p_use_intent bytea)');
 needle:='IF r.intent IS DISTINCT FROM p_intent OR r.character_id<>p_character';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing constructor replay binding'; END IF;
 body:=replace(body,needle,'IF r.use_intent IS DISTINCT FROM p_use_intent OR r.intent IS DISTINCT FROM p_intent OR r.character_id<>p_character');
 needle:='world_id,house_key,intent,action,before_item,after_key,house_location,inventory_location,before_timer)';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing constructor original-intent columns'; END IF;
 body:=replace(body,needle,'world_id,house_key,intent,action,before_item,after_key,house_location,inventory_location,before_timer,use_intent)');
 needle:='(SELECT to_jsonb(t) FROM game_item_timed_states t WHERE t.item_instance_id=p_item));';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing constructor original-intent values'; END IF;
 body:=replace(body,needle,'(SELECT to_jsonb(t) FROM game_item_timed_states t WHERE t.item_instance_id=p_item),p_use_intent);');
 needle:='BEGIN';
 body:=overlay(body placing E'BEGIN\n IF p_action<>2 OR p_use_intent IS NULL OR octet_length(p_use_intent) NOT BETWEEN 1 AND 529 THEN RAISE EXCEPTION ''WRAP_STALE''; END IF;\n'
  from regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i') for 5);
 EXECUTE body;
 -- A command402 retry cannot masquerade as a nativeUSE retry of the same id.
 body:=pg_get_functiondef('game_house_furniture_wrap_before_srv7_timers(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT)'::regprocedure);
 needle:='IF r.intent IS DISTINCT FROM p_intent OR r.character_id<>p_character';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'SRV7 missing legacy replay binding'; END IF;
 EXECUTE replace(body,needle,'IF r.use_intent IS NOT NULL OR r.intent IS DISTINCT FROM p_intent OR r.character_id<>p_character');
END $migration$;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY[
  'game_house_construction_source(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,UUID)'::regprocedure,
  'game_house_furniture_construct(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT,NUMERIC,UUID,NUMERIC,NUMERIC,SMALLINT,BYTEA,BYTEA,TEXT,INTEGER,TEXT,BYTEA)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',f);
 END LOOP;
END $$;

-- A loop receipt's physical movement time is server authority. Its existing
-- DEFAULT is insufficient when the runtime role supplies an explicit timestamp.
CREATE FUNCTION game_srv7_loop_movement_clock_stamp() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 NEW.created_at:=clock_timestamp();
 RETURN NEW;
END $$;
CREATE TRIGGER game_srv7_loop_movement_clock_stamp BEFORE INSERT ON game_item_loop_move_receipts
 FOR EACH ROW EXECUTE FUNCTION game_srv7_loop_movement_clock_stamp();

REVOKE ALL ON FUNCTION game_srv7_loop_movement_clock_stamp() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- Crystal game.cpp:2418/2426 starts Item decay after a real movement.
-- Container:addLoot merely creates the default duration; it does not start it.
CREATE FUNCTION game_house_furniture_movement_start(p_tx UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_loop_move_receipts%ROWTYPE; l game_item_loop_move_lines%ROWTYPE;
 life game_house_furniture_lifetimes%ROWTYPE; started BIGINT;
BEGIN
 SELECT * INTO r FROM game_item_loop_move_receipts WHERE transaction_id=p_tx;
 IF r.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() THEN
  RAISE EXCEPTION 'furniture duration starts only with original movement' USING ERRCODE='23514'; END IF;
 started:=floor(extract(epoch FROM r.created_at)*1000)::bigint;
 FOR l IN SELECT * FROM game_item_loop_move_lines WHERE transaction_id=p_tx
  AND definition_production_key IN('oteryn:item.tibia.i9034','oteryn:item.tibia.i9039',
   'oteryn:item.tibia.i35949','oteryn:item.tibia.i35951','oteryn:item.tibia.i35969','oteryn:item.tibia.i35971')
  AND quantity_before=1 AND quantity_after=1 AND from_kind<>0 AND to_kind<>0 LOOP
  IF EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=l.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=l.item_instance_id) THEN CONTINUE; END IF;
  SELECT * INTO life FROM game_house_furniture_lifetimes
   WHERE 'oteryn:item.tibia.i'||item_id::text=l.definition_production_key;
  IF life.duration_ms IS NULL OR life.target_id IS NULL THEN
   RAISE EXCEPTION 'qualified rotating furniture lost duration source' USING ERRCODE='23514'; END IF;
   duration_millis,expires_at_unix_ms,definition_family,definition_production_key,definition_revision,
   target_family,target_production_key,target_revision,content_digest)
  VALUES(l.item_instance_id,r.transaction_id,l.line_ordinal,life.duration_ms,started+life.duration_ms,
   l.definition_family,l.definition_production_key,l.definition_revision_ref,'Item',
   'oteryn:item.tibia.i'||life.target_id::text,l.definition_revision_ref,r.content_digest);
 END LOOP;
END $$;
DO $migration$ DECLARE body TEXT; arm TEXT; begin_at INTEGER; BEGIN
 body:=pg_get_functiondef('game_spell_item_temporal_schedule_proven()'::regprocedure);
 begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
 IF begin_at=0 THEN RAISE EXCEPTION 'missing Item temporal source proof'; END IF;
 arm:=$arm$
 IF EXISTS(SELECT 1 FROM game_item_loop_move_receipts srv7_furniture_receipt JOIN game_item_loop_move_lines l USING(transaction_id)
  JOIN game_item_instances i USING(item_instance_id) JOIN game_house_furniture_lifetimes life
   ON 'oteryn:item.tibia.i'||life.item_id::text=l.definition_production_key
  WHERE srv7_furniture_receipt.transaction_id=NEW.source_transaction_id AND l.line_ordinal=NEW.source_ordinal
   AND l.item_instance_id=NEW.item_instance_id AND l.created_xact_id=pg_current_xact_id()
   AND srv7_furniture_receipt.created_xact_id=pg_current_xact_id() AND NEW.created_xact_id=pg_current_xact_id()
   AND i.lifecycle=1 AND i.quantity=1 AND l.quantity_before=1 AND l.quantity_after=1
   AND l.from_kind<>0 AND l.to_kind<>0
   AND life.item_id IN(9034,9039,35949,35951,35969,35971)
   AND (i.definition_family,i.definition_production_key,i.definition_revision_ref)=
    (NEW.definition_family,NEW.definition_production_key,NEW.definition_revision)
   AND (l.definition_family,l.definition_production_key,l.definition_revision_ref)=
    (NEW.definition_family,NEW.definition_production_key,NEW.definition_revision)
   AND NEW.duration_millis=life.duration_ms
   AND NEW.expires_at_unix_ms=floor(extract(epoch FROM srv7_furniture_receipt.created_at)*1000)::bigint+life.duration_ms
   AND NEW.target_family='Item' AND NEW.target_production_key='oteryn:item.tibia.i'||life.target_id::text
   AND NEW.target_revision=NEW.definition_revision AND NEW.content_digest=srv7_furniture_receipt.content_digest
   AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id))
 THEN RETURN NULL; END IF;
 $arm$;
 EXECUTE substring(body FROM 1 FOR begin_at+4)||E'\n'||arm||substring(body FROM begin_at+5);
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_house_furniture_movement_start(uuid) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_house_furniture_movement_start(uuid) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_house_furniture_movement_start(uuid) TO oteryn_game_runtime;

-- Actual corpse-entry pickup uses TRANSFER, while ordinary Ground drag uses
-- item-loop movement. Both first-movement callers feed the same absolute owner.
ALTER TABLE game_item_transfer_receipts ADD COLUMN furniture_content_digest BYTEA
 CHECK(furniture_content_digest IS NULL OR octet_length(furniture_content_digest)=32);
-- Physical clock authority is independent of the immutable audit occurrence.
-- Nullable metadata preserves historical receipts without a volatile backfill.
ALTER TABLE game_item_transfer_receipts ADD COLUMN physical_started_at_unix_ms BIGINT
 CHECK(physical_started_at_unix_ms IS NULL OR physical_started_at_unix_ms>0);
CREATE FUNCTION game_srv7_transfer_physical_start_stamp() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF NEW.furniture_content_digest IS NOT NULL OR to_jsonb(NEW)->>'santa_toy_content_digest' IS NOT NULL THEN
  NEW.physical_started_at_unix_ms:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
 ELSE NEW.physical_started_at_unix_ms:=NULL; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER game_srv7_transfer_physical_start_stamp BEFORE INSERT ON game_item_transfer_receipts
 FOR EACH ROW EXECUTE FUNCTION game_srv7_transfer_physical_start_stamp();
REVOKE ALL ON FUNCTION game_srv7_transfer_physical_start_stamp() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_house_furniture_transfer_start(p_tx UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_transfer_receipts%ROWTYPE; i game_item_instances%ROWTYPE;
 life game_house_furniture_lifetimes%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_transfer_receipts WHERE transaction_id=p_tx;
 IF r.furniture_content_digest IS NULL THEN RETURN; END IF;
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id;
 IF r.created_xact_id<>pg_current_xact_id() OR r.shape<>2 OR r.source_quantity_before<>1
  OR r.source_quantity_after<>1 OR i.lifecycle<>1 OR i.quantity<>1
  OR i.last_transaction_id<>r.transaction_id THEN
  RAISE EXCEPTION 'furniture clock starts only with original exact pickup' USING ERRCODE='23514'; END IF;
 SELECT * INTO life FROM game_house_furniture_lifetimes WHERE item_id IN(9034,9039,35949,35951,35969,35971)
  AND 'oteryn:item.tibia.i'||item_id::text=i.definition_production_key;
 IF life.duration_ms IS NULL OR life.target_id IS NULL THEN
  RAISE EXCEPTION 'furniture pickup duration source changed' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id) THEN RETURN; END IF;
  duration_millis,expires_at_unix_ms,definition_family,definition_production_key,definition_revision,
  target_family,target_production_key,target_revision,content_digest)
 VALUES(i.item_instance_id,r.transaction_id,1,life.duration_ms,r.physical_started_at_unix_ms+life.duration_ms,
  i.definition_family,i.definition_production_key,i.definition_revision_ref,'Item',
  'oteryn:item.tibia.i'||life.target_id::text,i.definition_revision_ref,r.furniture_content_digest);
END $$;
DO $migration$ DECLARE body TEXT; arm TEXT; begin_at INTEGER; BEGIN
 body:=pg_get_functiondef('game_spell_item_temporal_schedule_proven()'::regprocedure);
 begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
 IF begin_at=0 THEN RAISE EXCEPTION 'missing absolute Item source proof'; END IF;
 arm:=$arm$
 IF EXISTS(SELECT 1 FROM game_item_transfer_receipts srv7_furniture_receipt JOIN game_item_instances i
  ON i.item_instance_id=srv7_furniture_receipt.source_item_instance_id JOIN game_house_furniture_lifetimes life
  ON 'oteryn:item.tibia.i'||life.item_id::text=i.definition_production_key
  WHERE srv7_furniture_receipt.transaction_id=NEW.source_transaction_id AND NEW.source_ordinal=1
   AND srv7_furniture_receipt.source_item_instance_id=NEW.item_instance_id AND srv7_furniture_receipt.created_xact_id=pg_current_xact_id()
   AND NEW.created_xact_id=pg_current_xact_id() AND srv7_furniture_receipt.shape=2 AND srv7_furniture_receipt.source_quantity_before=1
   AND srv7_furniture_receipt.source_quantity_after=1 AND i.lifecycle=1 AND i.quantity=1 AND i.last_transaction_id=srv7_furniture_receipt.transaction_id
   AND life.item_id IN(9034,9039,35949,35951,35969,35971)
   AND (i.definition_family,i.definition_production_key,i.definition_revision_ref)=
    (NEW.definition_family,NEW.definition_production_key,NEW.definition_revision)
   AND NEW.duration_millis=life.duration_ms AND NEW.expires_at_unix_ms=srv7_furniture_receipt.physical_started_at_unix_ms+life.duration_ms
   AND NEW.target_family='Item' AND NEW.target_production_key='oteryn:item.tibia.i'||life.target_id::text
   AND NEW.target_revision=NEW.definition_revision AND NEW.content_digest=srv7_furniture_receipt.furniture_content_digest
   AND EXISTS(SELECT 1 FROM game_item_container_entries srv7_furniture_entry WHERE srv7_furniture_entry.item_instance_id=i.item_instance_id
    AND srv7_furniture_entry.character_id=srv7_furniture_receipt.character_id AND srv7_furniture_entry.parent_item_instance_id=srv7_furniture_receipt.destination_parent_item_instance_id
    AND srv7_furniture_entry.placement_ordinal=srv7_furniture_receipt.destination_ordinal AND srv7_furniture_entry.placed_transaction_id=srv7_furniture_receipt.transaction_id)
   AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id))
 THEN RETURN NULL; END IF;
 $arm$;
 EXECUTE substring(body FROM 1 FOR begin_at+4)||E'\n'||arm||substring(body FROM begin_at+5);
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_house_furniture_transfer_start(uuid) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_house_furniture_transfer_start(uuid) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_house_furniture_transfer_start(uuid) TO oteryn_game_runtime;
CREATE FUNCTION game_house_furniture_transfer_clock_proven() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM game_item_instances i WHERE i.item_instance_id=NEW.source_item_instance_id
  AND i.definition_production_key IN('oteryn:item.tibia.i9034','oteryn:item.tibia.i9039',
   'oteryn:item.tibia.i35949','oteryn:item.tibia.i35951','oteryn:item.tibia.i35969','oteryn:item.tibia.i35971'))
  -- A previously sealed lifetime does not depend on this new movement's
  -- optional content stamp. Creation still requires the source-qualified digest
  -- in game_house_furniture_transfer_start and its same-transaction proof.
  AND NOT (
   EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=NEW.source_item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=NEW.source_item_instance_id))
 THEN RAISE EXCEPTION 'source-qualified furniture pickup requires original lifetime' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_house_furniture_transfer_clock_proven AFTER INSERT ON game_item_transfer_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_house_furniture_transfer_clock_proven();
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_house_furniture_transfer_clock_proven() SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_house_furniture_transfer_clock_proven() FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_house_furniture_transfer_clock_proven() TO oteryn_game_runtime;

-- The Channel absolute Item clock already exists. A named-House resident needs
-- its current House fence when settling that same schedule; no new clock store.
CREATE TABLE game_house_furniture_absolute_expiries(
 transaction_id UUID PRIMARY KEY CHECK(game_character_is_uuid_v7(transaction_id)),
 item_instance_id UUID NOT NULL UNIQUE REFERENCES game_spell_item_temporal_schedules(item_instance_id),
 character_id UUID NOT NULL REFERENCES game_character_roots(character_id),
 context JSONB NOT NULL,before_item JSONB NOT NULL,after_item JSONB NOT NULL,
 schedule JSONB NOT NULL,location JSONB NOT NULL,provenance JSONB NOT NULL,
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id()
);
REVOKE ALL ON game_house_furniture_absolute_expiries FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_house_furniture_absolute_expiries TO oteryn_game_runtime,oteryn_game_control;
CREATE TRIGGER game_house_furniture_absolute_expiries_immutable BEFORE UPDATE OR DELETE ON game_house_furniture_absolute_expiries
 FOR EACH ROW EXECUTE FUNCTION game_item_immutable();
CREATE TRIGGER game_house_furniture_absolute_expiries_no_truncate BEFORE TRUNCATE ON game_house_furniture_absolute_expiries
 EXECUTE FUNCTION game_item_reject_truncate();
CREATE FUNCTION game_house_furniture_absolute_expiry_complete(p_tx UUID) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_house_furniture_absolute_expiries%ROWTYPE; p game_spell_item_temporal_schedules%ROWTYPE;
 expected JSONB; k TEXT;
BEGIN
 SELECT * INTO r FROM game_house_furniture_absolute_expiries WHERE transaction_id=p_tx;
 IF NOT FOUND OR r.created_xact_id<>pg_current_xact_id() THEN RETURN FALSE; END IF;
 PERFORM game_house_podium_fence((r.context->>'session')::uuid,r.character_id,
  (r.context->>'connection')::numeric,(r.context->>'lease')::numeric,(r.context->>'scope')::numeric,
  (r.context->>'node')::uuid,(r.context->>'node_revision')::numeric,(r.context->>'world')::uuid,r.context->>'house');
 SELECT * INTO p FROM game_spell_item_temporal_schedules WHERE item_instance_id=r.item_instance_id;
 IF NOT FOUND OR to_jsonb(p)<>r.schedule OR p.expires_at_unix_ms>(r.context->>'settled_at')::bigint
  OR p.definition_production_key NOT IN('oteryn:item.tibia.i9034','oteryn:item.tibia.i9039',
   'oteryn:item.tibia.i35949','oteryn:item.tibia.i35951','oteryn:item.tibia.i35969','oteryn:item.tibia.i35971')
  OR p.target_family IS DISTINCT FROM 'Item' OR p.target_production_key IS NULL
  OR (p.definition_family,p.definition_production_key,p.definition_revision) IS DISTINCT FROM
   (r.before_item->>'definition_family',r.before_item->>'definition_production_key',r.before_item->>'definition_revision_ref')
  OR r.before_item->>'lifecycle'<>'1' OR r.before_item->>'quantity'<>'1'
  OR r.before_item->>'world_id' IS DISTINCT FROM r.context->>'world'
  OR EXISTS(SELECT 1 FROM game_spell_item_temporal_receipts WHERE item_instance_id=r.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=r.item_instance_id)
 THEN RETURN FALSE; END IF;
 expected:=r.before_item||jsonb_build_object('definition_family',p.target_family,
  'definition_production_key',p.target_production_key,'definition_revision_ref',p.target_revision,
  'last_transaction_id',r.transaction_id,'state_revision',(r.before_item->>'state_revision')::numeric+1);
 IF r.after_item<>expected OR NOT EXISTS(SELECT 1 FROM game_item_instances i
  WHERE i.item_instance_id=r.item_instance_id AND to_jsonb(i)=r.after_item) THEN RETURN FALSE; END IF;
 k:=r.location->>'custody_kind';
 RETURN CASE k
 WHEN 'house' THEN EXISTS(SELECT 1 FROM game_item_house_interior_locations h JOIN game_item_house_reclaim_provenance provenance USING(item_instance_id)
  WHERE h.item_instance_id=r.item_instance_id AND to_jsonb(h)=r.location->'custody' AND to_jsonb(provenance)=r.provenance)
 WHEN 'container' THEN EXISTS(SELECT 1 FROM game_item_container_entries e WHERE e.item_instance_id=r.item_instance_id
  AND to_jsonb(e)=r.location->'custody' AND e.character_id=r.character_id)
 WHEN 'nested' THEN EXISTS(SELECT 1 FROM game_item_nested_entries e,LATERAL game_item_loop_owner(e.parent_item_instance_id) owner
  WHERE e.item_instance_id=r.item_instance_id AND to_jsonb(e)=r.location->'custody'
   AND owner.owner_character=r.character_id AND owner.depth BETWEEN 0 AND 7)
 WHEN 'equipment' THEN EXISTS(SELECT 1 FROM game_character_equipment_slots e WHERE e.item_instance_id=r.item_instance_id
  AND to_jsonb(e)=r.location->'custody' AND e.character_id=r.character_id)
 ELSE FALSE END;
END $$;
CREATE FUNCTION game_house_furniture_absolute_expiry_proven() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF game_house_furniture_absolute_expiry_complete(NEW.transaction_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'House absolute furniture expiry lacks current fence and exact successor' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_house_furniture_absolute_expiry_proven AFTER INSERT ON game_house_furniture_absolute_expiries
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_house_furniture_absolute_expiry_proven();
CREATE FUNCTION game_house_furniture_absolute_expire(p_session UUID,p_character UUID,p_connection NUMERIC,
 p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT)
 RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE candidate RECORD; src RECORD; p game_spell_item_temporal_schedules%ROWTYPE;
 total INTEGER:=0; tx UUID; settled BIGINT; after_item JSONB;
BEGIN
 PERFORM game_house_podium_fence(p_session,p_character,p_connection,p_lease,p_scope,p_node,p_node_revision,p_world,p_house);
 PERFORM 1 FROM game_character_roots WHERE character_id=p_character FOR UPDATE;
 PERFORM 1 FROM game_house_properties WHERE world_id=p_world AND house_key=p_house FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended('oteryn:house-items:'||p_world::text||':'||p_house,0));
 settled:=floor(extract(epoch FROM statement_timestamp())*1000)::bigint;
 FOR candidate IN SELECT i.item_instance_id FROM game_item_instances i JOIN game_spell_item_temporal_schedules schedule USING(item_instance_id)
  LEFT JOIN game_item_house_interior_locations h USING(item_instance_id)
  LEFT JOIN LATERAL game_item_loop_owner(i.item_instance_id) owner ON TRUE
  WHERE i.world_id=p_world AND i.lifecycle=1 AND i.quantity=1
   AND i.definition_production_key IN('oteryn:item.tibia.i9034','oteryn:item.tibia.i9039',
    'oteryn:item.tibia.i35949','oteryn:item.tibia.i35951','oteryn:item.tibia.i35969','oteryn:item.tibia.i35971')
   AND schedule.expires_at_unix_ms<=settled
   AND (i.definition_family,i.definition_production_key,i.definition_revision_ref)=
    (schedule.definition_family,schedule.definition_production_key,schedule.definition_revision)
   AND ((h.world_id=p_world AND h.house_key=p_house) OR owner.owner_character=p_character)
   AND NOT EXISTS(SELECT 1 FROM game_spell_item_temporal_receipts WHERE item_instance_id=i.item_instance_id)
   AND NOT EXISTS(SELECT 1 FROM game_house_furniture_absolute_expiries WHERE item_instance_id=i.item_instance_id)
  ORDER BY i.item_instance_id LIMIT 16 FOR UPDATE OF i,schedule LOOP
  SELECT * INTO src FROM game_item_action_house_source(p_session,p_character,p_connection,p_lease,p_scope,
   p_node,p_node_revision,p_world,p_house,candidate.item_instance_id);
  IF NOT FOUND THEN CONTINUE; END IF;
  SELECT * INTO p FROM game_spell_item_temporal_schedules WHERE item_instance_id=candidate.item_instance_id FOR UPDATE;
  IF p.target_family IS DISTINCT FROM 'Item' OR p.target_production_key IS NULL THEN CONTINUE; END IF;
  tx:=game_character_uuid_v7();
  after_item:=src.before_item||jsonb_build_object('definition_family',p.target_family,
   'definition_production_key',p.target_production_key,'definition_revision_ref',p.target_revision,
   'last_transaction_id',tx,'state_revision',(src.before_item->>'state_revision')::numeric+1);
   before_item,after_item,schedule,location,provenance)
  VALUES(tx,candidate.item_instance_id,p_character,jsonb_build_object('session',p_session,'connection',p_connection,
   'lease',p_lease,'scope',p_scope,'node',p_node,'node_revision',p_node_revision,'world',p_world,
   'house',p_house,'settled_at',settled),src.before_item,after_item,to_jsonb(p),src.location,src.provenance);
  UPDATE game_item_instances SET definition_family=p.target_family,definition_production_key=p.target_production_key,
   definition_revision_ref=p.target_revision,last_transaction_id=tx,state_revision=state_revision+1
   WHERE item_instance_id=candidate.item_instance_id;
  total:=total+1;
 END LOOP;
 RETURN total;
END $$;
DO $migration$ DECLARE name TEXT; body TEXT; arm TEXT; begin_at INTEGER; BEGIN
 FOREACH name IN ARRAY ARRAY['game_item_instance_guard','game_item_instance_change_proven'] LOOP
  body:=pg_get_functiondef((name||'()')::regprocedure);
  begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
  IF begin_at=0 THEN RAISE EXCEPTION 'missing House absolute item guard'; END IF;
  IF name='game_item_instance_guard' THEN arm:=$arm$
   IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM game_house_furniture_absolute_expiries srv7_furniture_receipt
    WHERE srv7_furniture_receipt.transaction_id=NEW.last_transaction_id AND srv7_furniture_receipt.before_item=to_jsonb(OLD)
     AND srv7_furniture_receipt.after_item=to_jsonb(NEW) AND srv7_furniture_receipt.created_xact_id=pg_current_xact_id()) THEN RETURN NEW; END IF;
  $arm$;
  ELSE arm:=$arm$
   IF game_house_furniture_absolute_expiry_complete(NEW.last_transaction_id) THEN RETURN NULL; END IF;
  $arm$;
  END IF;
  EXECUTE substring(body FROM 1 FOR begin_at+4)||E'\n'||arm||substring(body FROM begin_at+5);
 END LOOP;
END $migration$;
ALTER FUNCTION game_house_furniture_destroy_expire(UUID,UUID,NUMERIC,NUMERIC,NUMERIC,UUID,NUMERIC,UUID,TEXT)
 RENAME TO game_house_furniture_destroy_expire_before_srv7_absolute;
CREATE FUNCTION game_house_furniture_destroy_expire(p_session UUID,p_character UUID,p_connection NUMERIC,
 p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT)
 RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 RETURN game_house_furniture_destroy_expire_before_srv7_absolute(p_session,p_character,p_connection,p_lease,p_scope,
  p_node,p_node_revision,p_world,p_house)+game_house_furniture_absolute_expire(p_session,p_character,p_connection,p_lease,p_scope,
  p_node,p_node_revision,p_world,p_house);
END $$;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY['game_house_furniture_absolute_expiry_complete(uuid)'::regprocedure,
  'game_house_furniture_absolute_expiry_proven()'::regprocedure,
  'game_house_furniture_absolute_expire(uuid,uuid,numeric,numeric,numeric,uuid,numeric,uuid,text)'::regprocedure,
  'game_house_furniture_destroy_expire(uuid,uuid,numeric,numeric,numeric,uuid,numeric,uuid,text)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION game_house_furniture_destroy_expire(uuid,uuid,numeric,numeric,numeric,uuid,numeric,uuid,text) TO oteryn_game_runtime;

-- Crystal enchanting.lua:107-112; paid enchantment preserves clicked Ground/House UUID.
CREATE FUNCTION game_dracoyle_in_place_record(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(r.recipe='oteryn:seasonal.dracoyle' AND r.source_kind IN(1,3,4,5)
  AND r.effects->>'dracoyle_in_place'='true',FALSE)
$$;
CREATE FUNCTION game_dracoyle_in_place_custody(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT CASE WHEN r.source_kind=5 THEN game_item_action_house_custody(r)
  WHEN r.source_kind=1 THEN game_item_action_furniture_custody(r)
  WHEN r.source_kind IN(3,4) THEN game_item_action_custody_current(r) ELSE FALSE END
$$;
CREATE FUNCTION game_dracoyle_in_place_admit(r game_item_consume_transform_records) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE i game_item_instances%ROWTYPE;e JSONB;node UUID;node_revision NUMERIC;t JSONB;
BEGIN
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id FOR UPDATE;
 SELECT to_jsonb(timer) INTO t FROM game_item_timed_states timer WHERE timer.item_instance_id=r.source_item_instance_id FOR UPDATE;
 IF game_dracoyle_in_place_record(r) IS DISTINCT FROM TRUE OR i.item_instance_id IS NULL
  OR to_jsonb(i) IS DISTINCT FROM r.before_item OR r.before_secondary IS DISTINCT FROM r.before_item
  OR r.secondary_item_instance_id IS DISTINCT FROM r.source_item_instance_id OR r.consume_source OR r.source_count<>0
  OR r.outputs<>'[]'::jsonb OR jsonb_array_length(r.extra_inputs)<>1 OR ((r.source_kind IN(1,4)) IS DISTINCT FROM (r.parent_item_instance_id IS NOT NULL))
  OR i.lifecycle<>1 OR i.quantity<>1 OR i.world_id<>r.world_id OR i.definition_family<>'Item'
  OR i.definition_production_key NOT IN('oteryn:item.tibia.i9035','oteryn:item.tibia.i9040')
  OR i.state_revision>=18446744073709551615 OR r.content_digest IS NULL
  OR game_dracoyle_in_place_custody(r) IS DISTINCT FROM TRUE
  OR r.effects->'house_after' IS DISTINCT FROM jsonb_build_object('key',CASE WHEN i.definition_production_key='oteryn:item.tibia.i9035' THEN 'oteryn:item.tibia.i9034' ELSE 'oteryn:item.tibia.i9039' END,'revision',i.definition_revision_ref)
  OR r.effects->>'kind' IS DISTINCT FROM 'transform' OR r.effects->>'source_item_id' IS DISTINCT FROM substring(i.definition_production_key FROM 20)
  OR r.effects->'cues' IS DISTINCT FROM '[{"binding":"appearance:effect/magic_green","effect_id":18}]'::jsonb
  OR r.effects->'house_temporal' IS DISTINCT FROM jsonb_build_object('before',t,'duration',604800000,'target',i.definition_production_key)
  OR (r.source_kind IN(1,4) AND t IS NULL) OR t->>'charges' IS NOT NULL OR t->>'deadline_at' IS NOT NULL
  OR EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules p WHERE p.item_instance_id=i.item_instance_id
   AND NOT EXISTS(SELECT 1 FROM game_spell_item_temporal_receipts d WHERE d.item_instance_id=i.item_instance_id)
   AND NOT EXISTS(SELECT 1 FROM game_house_furniture_absolute_expiries d WHERE d.item_instance_id=i.item_instance_id))
  OR EXISTS(SELECT 1 FROM game_item_keys WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_texts WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_imbuements WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_container_entries WHERE parent_item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_nested_entries WHERE parent_item_instance_id=i.item_instance_id)
 THEN RAISE EXCEPTION 'Dracoyle requires exact inactive same-custody predecessor and seven-day clock' USING ERRCODE='23514'; END IF;
 e:=r.extra_inputs->0;
 IF e->'before'->>'definition_production_key' IS DISTINCT FROM 'oteryn:item.tibia.i677'
  OR e->'before'->>'definition_family' IS DISTINCT FROM 'Item' OR e->>'count' IS DISTINCT FROM '1'
 THEN RAISE EXCEPTION 'Dracoyle spends exactly one real carried emerald' USING ERRCODE='23514'; END IF;
 PERFORM game_item_action_extra_admit(r);
 node:=(r.effects->'dracoyle_node'->>'id')::uuid;
 node_revision:=(r.effects->'dracoyle_node'->>'revision')::numeric;
 IF node IS NULL OR node_revision IS NULL OR game_runtime_scope_assignment_history_valid() IS DISTINCT FROM TRUE
  OR game_node_lock_current_registration(node,node_revision) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Dracoyle enchant requires current Node registration' USING ERRCODE='23514'; END IF;
 IF r.source_kind=5 THEN
  IF node IS DISTINCT FROM (r.source_location->>'node')::uuid
   OR node_revision IS DISTINCT FROM (r.source_location->>'node_revision')::numeric THEN
   RAISE EXCEPTION 'Dracoyle enchant House Node mismatch' USING ERRCODE='23514'; END IF;
  PERFORM game_house_podium_fence(r.game_session_id,r.character_id,
   (r.audit_context->>'connection_generation')::numeric,(r.audit_context->>'lease_generation')::numeric,
   (r.audit_context->>'scope_generation')::numeric,node,node_revision,r.world_id,r.source_location->'house'->>'house_key');
 ELSE
  IF node IS NULL OR node_revision IS NULL
   OR game_runtime_scope_assignment_history_valid() IS DISTINCT FROM TRUE
   OR game_node_lock_current_registration(node,node_revision) IS DISTINCT FROM TRUE
   OR NOT EXISTS(SELECT 1 FROM game_durability_reconnect_sessions s
    JOIN game_durability_admission_character_guards c ON c.character_id=s.character_id AND c.account_id=s.account_id
    JOIN game_durability_admission_account_guards a ON a.account_id=c.account_id
    JOIN game_runtime_scope_assignments runtime ON runtime.scope_kind=1 AND runtime.world_id=r.world_id
     AND runtime.channel_id=s.runtime_scope_channel_id
    JOIN game_durability_admission_runtime_guards g ON g.scope_key=runtime.scope_key
    WHERE s.game_session_id=r.game_session_id AND s.character_id=r.character_id AND s.world_id=r.world_id
     AND s.session_state IN(1,2) AND s.runtime_scope_kind=1 AND s.runtime_scope_world_id=r.world_id
     AND s.current_generation=(r.audit_context->>'connection_generation')::numeric
     AND s.character_lease_generation=(r.audit_context->>'lease_generation')::numeric
     AND s.scope_ownership_generation=(r.audit_context->>'scope_generation')::numeric
     AND c.eligible AND c.lease_generation=s.character_lease_generation AND c.holder_game_session_id=s.game_session_id
     AND a.presence_character_id=c.character_id AND a.holder_game_session_id=s.game_session_id
     AND runtime.state=1 AND runtime.ownership_generation=s.scope_ownership_generation
     AND runtime.holder_node_id=node AND runtime.holder_registration_revision=node_revision
     AND (r.source_kind<>3 OR EXISTS(SELECT 1 FROM game_item_ground_locations ground
      WHERE ground.item_instance_id=r.source_item_instance_id AND ground.channel_id=s.runtime_scope_channel_id
       AND ground.world_id=r.world_id AND ground.runtime_scope_ownership_generation=s.scope_ownership_generation))
     AND g.ready AND g.ownership_generation=runtime.ownership_generation)
  THEN RAISE EXCEPTION 'Dracoyle enchant requires current Character and Node' USING ERRCODE='23514'; END IF;
 END IF;
END $$;
CREATE FUNCTION game_dracoyle_in_place_complete(p_tx UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;i game_item_instances%ROWTYPE;t game_item_timed_states%ROWTYPE;expected JSONB;w game_item_timed_state_writes%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_tx;
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id;
 SELECT * INTO t FROM game_item_timed_states WHERE item_instance_id=r.source_item_instance_id;
 SELECT * INTO w FROM game_item_timed_state_writes WHERE transaction_id=p_tx;
 expected:=r.before_item||jsonb_build_object('definition_production_key',r.effects->'house_after'->>'key','last_transaction_id',p_tx,'state_revision',(r.before_item->>'state_revision')::numeric+1);
 IF game_dracoyle_in_place_record(r) IS DISTINCT FROM TRUE OR r.created_xact_id<>pg_current_xact_id()
  OR to_jsonb(i) IS DISTINCT FROM expected OR game_dracoyle_in_place_custody(r) IS DISTINCT FROM TRUE
  OR t.charges IS NOT NULL OR t.remaining_ms IS DISTINCT FROM 604800000::bigint
  OR t.deadline_at IS DISTINCT FROM r.occurred_at+604800000 OR game_house_furniture_timer_action_complete(w) IS DISTINCT FROM TRUE
 THEN RAISE EXCEPTION 'Dracoyle exact cost, item and clock completion missing' USING ERRCODE='23514'; END IF;
 PERFORM game_item_action_extra_complete(r);
END $$;
CREATE FUNCTION game_dracoyle_in_place_apply(p_tx UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_tx;
 IF game_dracoyle_in_place_record(r) IS DISTINCT FROM TRUE OR r.created_xact_id<>pg_current_xact_id() THEN
  RAISE EXCEPTION 'Dracoyle apply lacks exact current transaction' USING ERRCODE='23514'; END IF;
 UPDATE game_item_instances SET definition_production_key=r.effects->'house_after'->>'key',last_transaction_id=p_tx,state_revision=state_revision+1
  WHERE item_instance_id=r.source_item_instance_id AND to_jsonb(game_item_instances)=r.before_item;
 IF NOT FOUND THEN RAISE EXCEPTION 'Dracoyle predecessor changed' USING ERRCODE='23514'; END IF;
 PERFORM game_house_furniture_timer_apply(p_tx);
END $$;
DO $migration$
DECLARE n TEXT;body TEXT;arm TEXT;begin_at INTEGER;old TEXT;
BEGIN
 FOREACH n IN ARRAY ARRAY['game_item_action_no_consume_shape','game_item_action_source_custody'] LOOP
  SELECT pg_get_constraintdef(oid) INTO body FROM pg_constraint WHERE conrelid='game_item_consume_transform_records'::regclass AND conname=n;
  IF body IS NULL OR left(body,7)<>'CHECK (' THEN RAISE EXCEPTION 'Dracoyle source constraint missing: %',n; END IF;
  EXECUTE format('ALTER TABLE game_item_consume_transform_records DROP CONSTRAINT %I',n);
